- Improve ListView marker detection

##### TEST CASE
```JS
const win = Ti.UI.createWindow();
const listView = Ti.UI.createListView();

function addSection() {
	const items = [];

	for (let i = 0; i < 10; i++) {
		items.push({
			properties: { title: `Item #${i}` }
		});
	}

	const section = Ti.UI.createListSection({
		headerTitle: `Section #${listView.sections.length}`,
		items
	});
	listView.appendSection(section);

	listView.setMarker({
		sectionIndex: listView.sections.length - 1,
		itemIndex: section.items.length - 1
	});
}

listView.addEventListener('marker', addSection);

win.addEventListener('open', addSection);
win.add(listView);
win.open();
```
